// Public-aircraft registry resolution: the aircraft info models, the
// make/model lookups and evidence, and the reference table consulted when
// normalizing registrations and aircraft models.
import Foundation
import UIKit

struct AircraftInfo: Codable {
    var model: String
    var modeS: String
    var aircraftType: String? = nil
    var suggestedCategory: String? = nil
    var source: String? = nil
    var registryMake: String? = nil
    var registryModel: String? = nil
    var engineType: String? = nil
    var engineMake: String? = nil
    var engineModel: String? = nil
    var airworthinessClass: String? = nil
    var certificationCategory: String? = nil
    var manufactureYear: Int? = nil
    var retrievedAt: Date? = nil
    var registration: String? = nil
    var serialNumber: String? = nil
    var modelEquipment: AircraftModelEvidence? = nil
    var modelEquipmentCheckedAt: Date? = nil
    var modelEquipmentIdentity: String? = nil
}

@MainActor enum AircraftLookup {
    nonisolated static let categories = ["Unspecified", "ASEL", "ASES", "AMEL", "AMES", "Helicopter", "Gyroplane", "Rotorcraft", "Powered lift", "Glider", "Balloon", "Airship", "Powered parachute land", "Powered parachute sea", "Weight-shift land", "Weight-shift sea", "FFS", "FTD", "ATD"]
    static func clean(_ text: String) -> String {
        text.uppercased().filter { $0.isLetter || $0.isNumber }
    }
    static func valid(_ registration: String) -> Bool {
        registration.count <= 6 && registration.range(of: "^N[1-9][0-9]{0,4}[A-HJ-NP-Z]{0,2}$", options: .regularExpression) != nil
    }
    static func value(_ label: String, in html: String) -> String {
        let escaped = NSRegularExpression.escapedPattern(for: label)
        let patterns = [
            "<td[^>]*data-label=[\"']" + escaped + "[\"'][^>]*>(.*?)</td>",
            "<(?:td|th)[^>]*>\\s*" + escaped + "\\s*:?[\\s]*</(?:td|th)>\\s*<td[^>]*>(.*?)</td>"
        ]
        for pattern in patterns {
            if let match = WebData.matches(pattern, in: html).first {
                let result = WebData.plain(match).replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
                if !result.isEmpty { return result }
            }
        }
        return ""
    }
    static func category(type: String, model: String) -> String? {
        let text = (type + " " + model).uppercased()
        if text.contains("GLIDER") || text.contains("SAILPLANE") { return "Glider" }
        if text.contains("GYRO") { return "Gyroplane" }
        if text.contains("HELICOPTER") || text.contains("ROTOR") { return "Helicopter" }
        if text.contains("POWERED LIFT") || text.contains("POWERED-LIFT") { return "Powered lift" }
        if text.contains("BALLOON") { return "Balloon" }
        if text.contains("AIRSHIP") || text.contains("BLIMP") { return "Airship" }
        let sea = ["SEAPLANE", "FLOATPLANE", "AMPHIB", "FLYING BOAT"].contains { text.contains($0) }
        if text.contains("MULTI") { return sea ? "AMES" : "AMEL" }
        if text.contains("SINGLE") { return sea ? "ASES" : "ASEL" }
        return nil
    }
    static func parse(_ html: String) -> AircraftInfo? {
        let model = value("Model", in: html)
        let make = value("Manufacturer Name", in: html)
        let type = ["Aircraft Type", "Type Aircraft"].map { value($0, in: html) }.first { !$0.isEmpty } ?? ""
        let hex = value("Mode S Code (Base 16 / Hex)", in: html)
        guard !model.isEmpty else { return nil }
        let name = [make.capitalized, model].filter { !$0.isEmpty }.joined(separator: " ")
        return AircraftInfo(model: AircraftNames.display(name), modeS: hex, aircraftType: type,
                            suggestedCategory: category(type: type, model: name), source: "FAA Registry",
                            registryMake: make, registryModel: model, engineType: ["Engine Type", "Type Engine"].map { value($0, in: html) }.first { !$0.isEmpty } ?? "",
                            engineMake: value("Engine Manufacturer", in: html), engineModel: value("Engine Model", in: html),
                            airworthinessClass: value("Classification", in: html), certificationCategory: value("Category", in: html),
                            manufactureYear: Int(value("Mfr Year", in: html)), retrievedAt: Date(), serialNumber: value("Serial Number", in: html))
    }
    static func info(_ input: String, refresh: Bool = false,
                     now: Date = Date(),
                     fetch: @MainActor (URL) async throws -> Data = { try await WebData.data($0) }) async -> AircraftInfo? {
        let registration = clean(input)
        guard valid(registration) else { return nil }
        let key = "aircraftInfo-v5-" + registration
        func cached(_ name: String) -> AircraftInfo? {
            guard let data = UserDefaults.standard.data(forKey: name), var saved = try? JSONDecoder().decode(AircraftInfo.self, from: data),
                  saved.registration == nil || saved.registration == registration else { return nil }
            saved.model = AircraftNames.display(saved.model); return saved
        }
        let current = cached(key)
        let saved = current ?? cached("aircraftInfo-v4-" + registration) ?? cached("aircraftInfo-v3-" + registration) ?? cached("aircraftInfo-v2-" + registration)
        var result: AircraftInfo?
        if !refresh, let current, let date = current.retrievedAt,
           now.timeIntervalSince(date) >= 0, now.timeIntervalSince(date) < 14 * 86400 {
            result = current
        } else {
            let numericPart = String(registration.dropFirst())
            if let url = URL(string: "https://registry.faa.gov/aircraftinquiry/Search/NNumberResult?NNumberTxt=\(numericPart)"),
               let data = try? await fetch(url), !Task.isCancelled, let html = String(data: data, encoding: .utf8), var fresh = parse(html) {
                fresh.retrievedAt = now
                // Model equipment is shared by exact make/variant, independent of operator.
                if let saved, AircraftModelLookup.identity(saved) == AircraftModelLookup.identity(fresh) {
                    fresh.modelEquipment = saved.modelEquipment
                    fresh.modelEquipmentCheckedAt = saved.modelEquipmentCheckedAt
                    fresh.modelEquipmentIdentity = saved.modelEquipmentIdentity
                }
                result = fresh
            } else { result = saved }
        }
        guard !Task.isCancelled, var result else { return nil }
        result.registration = registration
        result = await AircraftModelLookup.enrich(result, refresh: refresh, now: now, fetch: fetch)
        guard !Task.isCancelled else { return nil }
        if let data = try? JSONEncoder().encode(result) { UserDefaults.standard.set(data, forKey: key) }
        return result
    }
}

// Broad make/model equipment lookup. FAA identifies the registered model; the
// public MyFlightbook model directory supplements stock equipment profiles.
// Never query rental operators or infer installed avionics from a model listing.

struct AircraftModelEvidence: Codable {
    var modelIdentity: String
    var category: String
    var features: [String: Bool]
    var sourceName: String
    var sourceURL: URL
    var checkedAt: Date
}

@MainActor enum AircraftModelLookup {
    struct Manufacturer: Codable { var name: String; var url: URL }
    struct Model: Codable {
        var name: String
        var category: String
        var attributes: [String]
        var url: URL
    }
    private struct ManufacturerCache: Codable { var rows: [Manufacturer]; var checkedAt: Date }
    private struct ModelCache: Codable { var rows: [Model]; var checkedAt: Date }
    static let directory = URL(string: "https://myflightbook.com/logbook/mvc/AllMakes")!
    private static let lifetime: TimeInterval = 14 * 86400
    private static let indexKey = "aircraftModelDirectory-v1"
    private static let modelPrefix = "aircraftModelEquipment-v1-"
    nonisolated static func makeKey(_ value: String) -> String {
        let key = AircraftReference.key(value)
        for (fragment, canonical) in [("CESSNA", "CESSNA"), ("BEECH", "BEECHCRAFT"),
            ("PIPER", "PIPER"), ("MOONEY", "MOONEY"), ("DIAMOND", "DIAMOND"),
            ("CIRRUS", "CIRRUS"), ("PILATUS", "PILATUS"), ("SOCATA", "SOCATA")]
            where key.contains(fragment) { return canonical }
        let words = value.uppercased().components(separatedBy: CharacterSet.alphanumerics.inverted)
        let suffixes: Set<String> = ["THE", "INC", "INCORPORATED", "LLC", "LTD", "LIMITED", "CO", "COMPANY", "CORP", "CORPORATION", "AIRCRAFT", "AIRPLANE", "INDUSTRIES", "INDUSTRIE", "GMBH"]
        return words.filter { !$0.isEmpty && !suffixes.contains($0) }.joined()
    }
    nonisolated static func codeKey(_ value: String, make: String) -> String {
        // Strip display-only marketing names and type-rating labels; preserve
        // conversion suffixes, float variants and every model-variant character.
        var code = value.replacingOccurrences(of: "\\\"[^\\\"]*\\\"", with: "", options: .regularExpression)
            .replacingOccurrences(of: "\\(Type:[^)]*\\)", with: "", options: [.regularExpression, .caseInsensitive])
        code = AircraftReference.key(code)
        let maker = makeKey(make)
        if maker == "CESSNA" || maker.contains("TEXTRON"), code.hasPrefix("C"), code.dropFirst().first?.isNumber == true { code.removeFirst() }
        if maker == "BEECHCRAFT" || maker.contains("TEXTRON"), code.hasPrefix("BE") { code = String(code.dropFirst(2)) }
        return code
    }
    nonisolated static func identity(_ info: AircraftInfo) -> String {
        let (make, model) = AircraftFeatures.parts(info.model, info: info)
        return makeKey(make) + "/" + codeKey(model, make: make)
    }
    static func text(_ html: String) -> String {
        WebData.plain(html).replacingOccurrences(of: "&quot;", with: "\"")
            .replacingOccurrences(of: "&#34;", with: "\"")
            .replacingOccurrences(of: "&#9;", with: " ")
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }
    static func link(_ href: String) -> URL? {
        guard let url = URL(string: href, relativeTo: directory)?.absoluteURL,
              url.scheme == "https", url.host == directory.host, url.query == nil,
              url.path.range(of: "^/logbook/mvc/AllMakes/[0-9]+(?:/[0-9]+)?$", options: .regularExpression) != nil else { return nil }
        return url
    }
    static func manufacturers(_ html: String) -> [Manufacturer] {
        let anchors = WebData.matches("(<a\\b[^>]*href=[\"'][^\"']+[\"'][^>]*>.*?</a>)", in: html)
        return anchors.compactMap { anchor in
            guard let href = WebData.matches("href=[\"']([^\"']+)[\"']", in: anchor).first,
                  let url = link(href), url.path.split(separator: "/").count == 4 else { return nil }
            let name = text(anchor)
            return name.isEmpty ? nil : Manufacturer(name: name, url: url)
        }
    }
    static func models(_ html: String, manufacturer: Manufacturer) -> [Model] {
        var output: [Model] = []
        var pending: Model?
        for row in WebData.matches("<tr\\b[^>]*>(.*?)</tr>", in: html) {
            let cells = WebData.matches("<td\\b[^>]*>(.*?)</td>", in: row)
            if cells.count == 3 {
                pending = nil
                guard makeKey(text(cells[0])) == makeKey(manufacturer.name),
                      let anchor = WebData.matches("(<a\\b[^>]*href=[\"'][^\"']+[\"'][^>]*>.*?</a>)", in: cells[1]).first,
                      let href = WebData.matches("href=[\"']([^\"']+)[\"']", in: anchor).first,
                      let url = link(href), url.path.hasPrefix(manufacturer.url.path + "/") else { continue }
                pending = Model(name: text(anchor), category: text(cells[2]), attributes: [], url: url)
            } else if cells.count == 1, var model = pending,
                      row.range(of: "<ul\\b", options: [.regularExpression, .caseInsensitive]) != nil {
                model.attributes = WebData.matches("<li\\b[^>]*>(.*?)</li>", in: cells[0]).map(text)
                output.append(model); pending = nil
            } else { pending = nil }
        }
        return output
    }
    static func evidence(_ models: [Model], info: AircraftInfo, now: Date) -> AircraftModelEvidence? {
        let (make, code) = AircraftFeatures.parts(info.model, info: info)
        let category = info.suggestedCategory ?? "Unspecified"
        guard ["ASEL", "ASES", "AMEL", "AMES"].contains(category) else { return nil }
        // M20D can retain the same registry model after conversion from the
        // original fixed-gear configuration. Model alone cannot resolve it.
        // Manufacturer AFM: https://mooney.com/wp-content/uploads/2020/12/M20D-Fixed-AFM-pages.pdf
        if makeKey(make) == "MOONEY", codeKey(code, make: make) == "M20D" { return nil }
        let exact = models.filter {
            $0.category == category && codeKey($0.name, make: make) == codeKey(code, make: make)
                && !$0.attributes.contains("Jet")
        }
        guard let first = exact.first else { return nil }
        var features: [String: Bool] = [:]
        // Multiple records can describe optional installations or conversions.
        // Agreeing exact records are required; no family or substring fallback.
        if exact.allSatisfy({ $0.attributes.contains("Complex") }) {
            features["complex"] = true
            features["flaps"] = true; features["controllablePitchPropeller"] = true
            if ["ASEL", "AMEL"].contains(category) { features["retractableGear"] = true }
        } else if !exact.contains(where: { $0.attributes.contains("Complex") }) {
            for (attribute, feature) in [("Retractable Gear", "retractableGear"),
                ("Flaps", "flaps"), ("Controllable Pitch Prop", "controllablePitchPropeller")]
                where exact.allSatisfy({ $0.attributes.contains(attribute) }) { features[feature] = true }
        }
        // Catalog absence is not a confirmed negative. Do not import TAA,
        // autopilot, horsepower or other aircraft-specific claims from this list.
        guard !features.isEmpty else { return nil }
        return AircraftModelEvidence(modelIdentity: identity(info), category: category, features: features,
            sourceName: "MyFlightbook model equipment catalog", sourceURL: first.url, checkedAt: now)
    }
    private static func recent(_ date: Date, now: Date) -> Bool {
        let age = now.timeIntervalSince(date)
        return age >= 0 && age < lifetime
    }
    static func enrich(_ input: AircraftInfo, refresh: Bool = false, now: Date = Date(),
                       fetch: @MainActor (URL) async throws -> Data = { try await WebData.data($0) }) async -> AircraftInfo {
        var info = input
        let fingerprint = identity(info)
        let category = info.suggestedCategory ?? "Unspecified"
        if info.modelEquipment?.modelIdentity != fingerprint || info.modelEquipment?.category != category { info.modelEquipment = nil }
        // Known stock equipment needs no external model-directory request.
        var stockInfo = info; stockInfo.modelEquipment = nil
        if AircraftFeatures.detect(info.model, category: category, info: stockInfo).values["complex"] != nil {
            info.modelEquipment = nil; return info
        }
        guard ["ASEL", "ASES", "AMEL", "AMES"].contains(category) else { return info }
        if !refresh, info.modelEquipmentIdentity == fingerprint + "/" + category,
           let checked = info.modelEquipmentCheckedAt, recent(checked, now: now) { return info }
        let defaults = UserDefaults.standard
        let oldIndex = defaults.data(forKey: indexKey).flatMap { try? JSONDecoder().decode(ManufacturerCache.self, from: $0) }
        let index: [Manufacturer]
        if !refresh, let cached = oldIndex, recent(cached.checkedAt, now: now) { index = cached.rows }
        else {
            if let data = try? await fetch(directory), !Task.isCancelled,
               let html = String(data: data, encoding: .utf8), !manufacturers(html).isEmpty {
                index = manufacturers(html)
                if let encoded = try? JSONEncoder().encode(ManufacturerCache(rows: index, checkedAt: now)) { defaults.set(encoded, forKey: indexKey) }
            } else { index = oldIndex?.rows ?? [] }
        }
        guard !Task.isCancelled, !index.isEmpty else { return info }
        let (make, _) = AircraftFeatures.parts(info.model, info: info)
        let key = makeKey(make)
        let candidates = index.filter {
            makeKey($0.name) == key || (key.contains("TEXTRON") && ["CESSNA", "BEECHCRAFT"].contains(makeKey($0.name)))
        }
        guard !candidates.isEmpty else { return info }
        var allModels: [Model] = []
        var completed = true
        for manufacturer in candidates {
            guard !Task.isCancelled else { return info }
            let cacheKey = modelPrefix + manufacturer.url.lastPathComponent
            let old = defaults.data(forKey: cacheKey).flatMap { try? JSONDecoder().decode(ModelCache.self, from: $0) }
            if !refresh, let cached = old, recent(cached.checkedAt, now: now) { allModels += cached.rows; continue }
            if let data = try? await fetch(manufacturer.url), !Task.isCancelled, let html = String(data: data, encoding: .utf8) {
                let parsed = models(html, manufacturer: manufacturer)
                if !parsed.isEmpty {
                    allModels += parsed
                    if let encoded = try? JSONEncoder().encode(ModelCache(rows: parsed, checkedAt: now)) { defaults.set(encoded, forKey: cacheKey) }
                    continue
                }
            }
            completed = false
            allModels += old?.rows ?? []
        }
        guard !Task.isCancelled else { return info }
        if completed {
            info.modelEquipment = evidence(allModels, info: info, now: now)
            info.modelEquipmentCheckedAt = now; info.modelEquipmentIdentity = fingerprint + "/" + category
        } else if info.modelEquipment == nil {
            // An offline result retains the original evidence date, never a fresh timestamp.
            let oldest = candidates.compactMap { manufacturer in
                defaults.data(forKey: modelPrefix + manufacturer.url.lastPathComponent)
                    .flatMap { try? JSONDecoder().decode(ModelCache.self, from: $0) }?.checkedAt
            }.min()
            if let oldest { info.modelEquipment = evidence(allModels, info: info, now: oldest) }
        }
        return info
    }
}

// FAA technical reference snapshot, 2026-10-03. N-number records are still refreshed online.
// Source: https://registry.faa.gov/database/ReleasableAircraft.zip (ACFTREF and ENGINE only).

nonisolated enum AircraftReference {
    struct Model: Sendable {
        var type: String
        var engineType: String
        var configuration: String
        var engines: Int?
        var weightClass: String
    }
    struct Engine: Sendable { var type: String; var horsepower: Double? }
    static func key(_ value: String) -> String {
        value.uppercased().filter { $0.isASCII && ($0.isLetter || $0.isNumber) }
    }
    static func unpack(_ encoded: String) -> [[String]] {
        guard let data = Data(base64Encoded: encoded, options: .ignoreUnknownCharacters),
              let text = String(data: data, encoding: .utf8) else { return [] }
        return text.split(separator: "\n").map { $0.split(separator: "|", omittingEmptySubsequences: false).map(String.init) }
    }
    static let models: [String: Model] = {
        var result: [String: Model] = [:]
        for row in unpack(modelRows) where row.count == 6 {
            result[row[0]] = Model(type: row[1], engineType: row[2], configuration: row[3], engines: Int(row[4]), weightClass: row[5])
        }
        return result
    }()
    static let engines: [String: Engine] = {
        var result: [String: Engine] = [:]
        for row in unpack(engineRows) where row.count == 3 {
            result[row[0]] = Engine(type: row[1], horsepower: Double(row[2]))
        }
        return result
    }()
    // Bare model fallback is allowed only when every reference agrees on the fields used.
    static let modelAliases: [String: Model] = {
        let groups = Dictionary(grouping: models, by: { String($0.key.split(separator: "/", omittingEmptySubsequences: false).last ?? "") })
        var result: [String: Model] = [:]
        for (code, rows) in groups where !code.isEmpty {
            func agreed(_ path: KeyPath<Model, String>) -> String {
                let values = Set(rows.map { $0.value[keyPath: path] }); return values.count == 1 ? values.first! : ""
            }
            let counts = Set(rows.compactMap { $0.value.engines })
            result[code] = Model(type: agreed(\.type), engineType: agreed(\.engineType), configuration: agreed(\.configuration),
                                engines: counts.count == 1 && rows.allSatisfy({ $0.value.engines != nil }) ? counts.first : nil,
                                weightClass: agreed(\.weightClass))
        }
        return result
    }()
    static func model(make: String, code: String) -> Model? {
        models[key(make) + "/" + key(code)] ?? modelAliases[key(code)]
    }
    static func engine(make: String, code: String) -> Engine? {
        engines[key(make) + "/" + key(code)]
    }
    private static let modelRows = """
        MUNBQlJBU09WLzFTMjhNMnwxfDF8MXwxfDEKNkNIVVRFUklOQy9TS1IyMTk5NHw4fDd8MXwxfDEKQTFBRFZFTlRVUkVTSU5DL0hBV0t8NHwxfDF8MXwxCkFBUkFJUkxJRlRHUk9VUElOQy9VSDYwQXw2fDN8MXwyfDMKQUJCRVlKT0hOUC9BQkJFWUtPTEJJSXw0fDd8MXwxfDEKQUJCWUFJUkxMQy8yMDAzUkFQVE9SfDh8
        N3wxfDF8MQpBQkVSTkFUSFlGUkVETS9DT1JCRU5KUkFDRXw0fDh8MXwxfDEKQUJGTFlHSU5EVVNUUkkvSlNXRUlIRXwxfDB8MXwwfDEKQUJGTFlHUExBTi9ERlNLUkFOSUNIMUJ8MXwwfDF8MHwxCkFDQ0VUVE9MQUZSQU5LVC9BSVJCT1JORUVER0VYfDd8N3wzfDF8MQpBQ0VBRVJPTkFVVElDU0xMQy9VSDYwQXw2fDN8
        MXwyfDMKQUNGVFNQUk1LVEdPTERFTkNJUkNMRUFSL1RCVDA2fDR8N3wxfDF8MQpBQ0hFU09OSEFST0xEL01JTklNQVgxNjAwUnw0fDd8MXwxfDEKQUNLTEFORExFU0UvVElUQU58NHw3fDF8MXwxCkFEQU1TQkFMTE9PTi9BMzdIfDJ8MHwxfDF8MQpBREFNU0JBTExPT04vQTUwU3wyfDB8MXwwfDEKQURBTVNCQUxMT09O
        L0E1MFNDfDJ8MHwxfDB8MQpBREFNU0JBTExPT04vQTU1fDJ8MHwxfDB8MQpBREFNU0JBTExPT04vQTU1U3wyfDB8MXwwfDEKQURBTVNCQUxMT09OL0FCfDJ8MHwxfDB8MQpBREFNU0JBTExPT04vTER8MnwwfDF8MHwxCkFEQU1TQkFMTE9PTi9MRFN8MnwwfDF8MHwxCkFEQU1TQkFMTE9PTkxPRlRMTEMvQTU1U3wyfDB8
